-- ════════════════════════════════════════════════════════════════
-- launchpad — Supabase schema  (as generated by Lovable)
-- ════════════════════════════════════════════════════════════════
-- This is the schema the app shipped with. It LOOKS fine: there's a
-- profiles table, RLS is turned on, and signup works. But the app
-- crashes on the dashboard right after signup.
--
-- 🐞 THE BUG (T-102):
--   • RLS is ENABLED on profiles  ✅ (good security default)
--   • There is a SELECT policy     ✅
--   • There is NO INSERT policy    ❌  ← the client insert is silently rejected
--   • There is NO trigger to create the profile row on signup ❌
--
-- Result: auth.users gets a row, profiles stays empty, and the
-- dashboard reads `null` for the profile → TypeError.
-- The fix lives in patch.sql.
-- ════════════════════════════════════════════════════════════════

create table if not exists profiles (
  id         uuid primary key references auth.users(id),
  full_name  text,
  created_at timestamptz default now()
);

-- RLS on, but only a read policy — no way for a user to INSERT their own row.
alter table profiles enable row level security;

create policy "read own profile"
  on profiles for select
  using (auth.uid() = id);

-- ⚠️ Missing: an INSERT policy.
-- ⚠️ Missing: a trigger to auto-create the profile on signup.
